param([string]$OfflinePackEvidence,[string]$OfflineDynamicEvidence,[string]$ServerEvidence,[string]$LiveCertificate,[string]$RevocationCode,[switch]$Promote)
$ErrorActionPreference='Stop'
$repository=Split-Path -Parent $PSScriptRoot;$root=Join-Path $repository 'app\engine\target\distribution';$candidatePath=Join-Path $root 'candidate.json'
if(-not(Test-Path -LiteralPath $candidatePath)){throw 'CANDIDATE_MISSING'}
$candidate=Get-Content -Raw -LiteralPath $candidatePath|ConvertFrom-Json
function Digest([string]$Path){if([string]::IsNullOrWhiteSpace($Path)-or -not(Test-Path -LiteralPath $Path)){return $null};(Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToLowerInvariant()}
function Evidence([string]$Path){if([string]::IsNullOrWhiteSpace($Path)){return $null};$resolved=(Resolve-Path -LiteralPath $Path).Path;[ordered]@{path=[IO.Path]::GetFileName($resolved);sha256=Digest $resolved}}
$verified=$true;$offlineReady=$OfflinePackEvidence -and $OfflineDynamicEvidence -and $ServerEvidence;$live=$offlineReady -and $LiveCertificate
$status=if($RevocationCode){'revoked'}elseif($live){'live-certified'}elseif($offlineReady){'offline-ready'}elseif($candidate.capability -eq 'development'){'development'}else{'verified'}
if($Promote){if($candidate.dirty -or $candidate.version.EndsWith('-SNAPSHOT')){throw 'PROMOTION_REQUIRES_CLEAN_RELEASE_VERSION'};$tag=(& git -C $repository tag --points-at $candidate.gitCommit);if($tag -notcontains "v$($candidate.version)"){throw 'PROMOTION_TAG_MISMATCH'};if(-not $offlineReady){throw 'PROMOTION_EVIDENCE_INCOMPLETE'}}
$manifest=[ordered]@{schemaVersion=1;status=$status;candidateId=$candidate.candidateId;productVersion=$candidate.version;gitCommit=$candidate.gitCommit;createdAt=[DateTimeOffset]::UtcNow.ToString('O');artifacts=[ordered]@{cliArchive=$candidate.archive;cliJarSha256=$candidate.cliJarSha256;serverJarSha256=$candidate.serverJarSha256;cliSbomSha256=$candidate.cliSbomSha256;serverSbomSha256=$candidate.serverSbomSha256};evidence=[ordered]@{offlinePack=Evidence $OfflinePackEvidence;offlineDynamic=Evidence $OfflineDynamicEvidence;serverPostgres=Evidence $ServerEvidence;liveCertificate=Evidence $LiveCertificate};testedMatrix=[ordered]@{jdk=@('25');database=@('PostgreSQL 16');os=@('windows','linux')};revocation=if($RevocationCode){[ordered]@{code=$RevocationCode;at=[DateTimeOffset]::UtcNow.ToString('O')}}else{$null};claimLimit='Engine/server release readiness only; no end-user web UI claim.'}
$out=Join-Path $root 'release-manifest.json';[IO.File]::WriteAllText($out,(($manifest|ConvertTo-Json -Depth 12)+"`n"),[Text.UTF8Encoding]::new($false));Write-Host "$status release manifest: $out"
